284	/** Keeps each sheet's crews, their leads and their members. */
285	@Service
286	public class CrewService {
287	
288	    private final CrewRepository crews;
289	    private final PersonRepository people;
290	    private final SheetService sheets;
291	    private final Audit audit;
292	
293	    public CrewService(CrewRepository crews, PersonRepository people, SheetService sheets, Audit audit) {
294	        this.crews = crews;
295	        this.people = people;
296	        this.sheets = sheets;
297	        this.audit = audit;
298	    }
299	
300	    /** The sheet's crews, in the order they were added. */
301	    @Transactional(readOnly = true)
302	    public List<Crew> list(String sheetId) {
303	        return crews.findBySheetIdOrderByIdAsc(sheetId);
304	    }
305	
306	    /** Add a crew by a name (surrounding spaces removed) with a lead from the sheet's people; a blank name, one
307	     *  already taken, or no lead, is refused. */
308	    @Transactional
309	    public Crew add(String sheetId, String user, String name, Long leadId) {
310	        sheets.today(sheetId);
311	        String n = name == null ? "" : name.trim();
312	        if (n.isEmpty()) {
313	            throw new CrewRefusedException("Enter a crew name.");
314	        }
315	        if (crews.existsBySheetIdAndName(sheetId, n)) {
316	            throw new CrewRefusedException("\"" + n + "\" is already a crew.");
317	        }
318	        Person lead = leadId == null ? null : people.findByIdAndSheetId(leadId, sheetId).orElse(null);
319	        if (lead == null) {
320	            throw new CrewRefusedException("Choose a lead.");
321	        }
322	        Crew saved = crews.saveAndFlush(new Crew(sheetId, n, lead.getId()));
323	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + n + " lead=" + lead.getName());
324	        return saved;
325	    }
326	
327	    /** Add a person of the sheet to a crew; its lead, or a person already in it, is refused. */
328	    @Transactional
329	    public Crew addMember(String sheetId, String user, long crewId, Long personId) {
330	        Crew crew = crews.findByIdAndSheetId(crewId, sheetId)
331	                .orElseThrow(() -> new CrewRefusedException("No such crew."));
332	        Person person = personId == null ? null : people.findByIdAndSheetId(personId, sheetId).orElse(null);
333	        if (person == null) {
334	            throw new CrewRefusedException("Choose a person.");
335	        }
336	        if (person.getId().equals(crew.getLeadId())) {
337	            throw new CrewRefusedException(person.getName() + " leads " + crew.getName() + ".");
338	        }
339	        if (crew.includes(person.getId())) {
340	            throw new CrewRefusedException(person.getName() + " is already in " + crew.getName() + ".");
341	        }
342	        crew.addMember(person.getId());
343	        Crew saved = crews.saveAndFlush(crew);
344	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
345	                + " name=" + person.getName());
346	        return saved;
347	    }
348	}
