381	/** A sheet's pools and their members. The signed-in user's name comes in the X-User header. */
382	@RestController
383	@Validated
384	@RequestMapping("/api/sheets/{sheetId}/pools")
385	public class PoolController {
386	
387	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
388	
389	    /** A member, a person or another pool (poolId set, never retired): a retired person (a retirement date set,
390	     *  whatever the date) counts its share toward the total but is left out of the cuts (0.00, its share spread
391	     *  over the others; none when every member is retired). Its cut of the pool's pot (two decimals; 0.00 for a person
392	     *  on hold on the sheet's today, whose share is spread over the others); none when the pool is unbalanced or
393	     *  has no pot. A member whose dates (from, to: optional) do not include the sheet's today is left out
394	     *  entirely: it counts 0.00 toward the total and has no cut. */
395	    public record PoolMemberView(Long personId, Long poolId, String name, String share, boolean retired, String cut,
396	            LocalDate from, LocalDate to, boolean active) {
397	    }
398	
399	    /** A pool, with its total share and whether that is exactly 100.00. */
400	    public record PoolView(long id, String name, List<PoolMemberView> members, String totalShare, boolean balanced) {
401	
402	        /** The sheet's pools as views, in their order. A pool that is a member of another has as its pot its cut
403	         *  in the pool above (none when that is unbalanced or has none); one that is a member of none has the
404	         *  sheet's pot. A person on hold on the sheet's today gets no cut from any pool. */
405	        static List<PoolView> of(List<Pool> pools, Map<Long, Person> people, BigDecimal sheetPot, LocalDate today) {
406	            Map<Long, Pool> byId = new HashMap<>();
407	            Map<Long, Pool> parentOf = new HashMap<>();
408	            for (Pool pool : pools) {
409	                byId.put(pool.getId(), pool);
410	                for (PoolMember m : pool.getMembers()) {
411	                    if (m.getMemberPoolId() != null) {
412	                        parentOf.put(m.getMemberPoolId(), pool);
413	                    }
414	                }
415	            }
416	            Map<Long, PoolView> views = new HashMap<>();
417	            for (Pool pool : pools) {
418	                view(pool, byId, parentOf, people, sheetPot, today, views);
419	            }
420	            return pools.stream().map(p -> views.get(p.getId())).toList();
421	        }
422	
423	        private static PoolView view(Pool pool, Map<Long, Pool> byId, Map<Long, Pool> parentOf,
424	                Map<Long, Person> people, BigDecimal sheetPot, LocalDate today, Map<Long, PoolView> views) {
425	            PoolView done = views.get(pool.getId());
426	            if (done != null) {
427	                return done;
428	            }
429	            BigDecimal pot = sheetPot;
430	            Pool parent = parentOf.get(pool.getId());
431	            if (parent != null) {
432	                PoolView above = view(parent, byId, parentOf, people, sheetPot, today, views);
433	                String cut = above.members().stream().filter(m -> pool.getId().equals(m.poolId())).findFirst()
434	                        .map(PoolMemberView::cut).orElse(null);
435	                pot = cut == null ? null : new BigDecimal(cut);
436	            }
437	            PoolView v = of(pool, byId, people, pot, today);
438	            views.put(pool.getId(), v);
439	            return v;
440	        }
441	
442	        private static PoolView of(Pool pool, Map<Long, Pool> pools, Map<Long, Person> people, BigDecimal pot,
443	                LocalDate today) {
444	            List<PoolMember> all = pool.getMembers();
445	            BigDecimal total = BigDecimal.ZERO.setScale(2);
446	            boolean[] retired = new boolean[all.size()];
447	            boolean[] held = new boolean[all.size()];
448	            boolean[] active = new boolean[all.size()];
449	            boolean allRetired = true;
450	            for (int i = 0; i < all.size(); i++) {
451	                Long personId = all.get(i).getPersonId();
452	                Person p = personId == null ? null : people.get(personId);
453	                retired[i] = p != null && p.isRetired();
454	                held[i] = p != null && today != null && p.heldOn(today);
455	                active[i] = today == null || all.get(i).activeOn(today);
456	                if (active[i]) {
457	                    total = total.add(all.get(i).getShare());
458	                    allRetired &= retired[i];
459	                }
460	            }
461	            boolean balanced = total.compareTo(HUNDRED) == 0;
462	            BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(all, retired, held, active, pot) : new BigDecimal[all.size()];
463	            List<PoolMemberView> members = new ArrayList<>();
464	            for (int i = 0; i < all.size(); i++) {
465	                PoolMember m = all.get(i);
466	                String name;
467	                if (m.getMemberPoolId() != null) {
468	                    Pool member = pools.get(m.getMemberPoolId());
469	                    name = member == null ? "" : member.getName();
470	                } else {
471	                    Person p = people.get(m.getPersonId());
472	                    name = p == null ? "" : p.getName();
473	                }
474	                members.add(new PoolMemberView(m.getPersonId(), m.getMemberPoolId(), name,
475	                        m.getShare().setScale(2).toPlainString(), retired[i],
476	                        cuts[i] == null ? null : cuts[i].toPlainString(), m.getFromDate(), m.getToDate(),
477	                        active[i]));
478	            }
479	            return new PoolView(pool.getId(), pool.getName(), members, total.setScale(2).toPlainString(), balanced);
480	        }
481	
482	        /** Each member's cut of the pot: the pot times their share divided by the shares of the members with a
483	         *  cut added up, rounded half to even to two decimals (0.00 for a retired one or one on hold, whose share is
484	         *  spread over the others in proportion to theirs); the
485	         *  remainder, the pot minus the cuts added up, goes to the member with the smallest non-zero cut, the
486	         *  latest added on a tie (when no cut is non-zero, to the last member with a cut and a share), so the cuts
487	         *  total exactly the pot. When no member has a cut, each is 0.00.
488	         *  A member not active on the sheet's today has none at all. */
489	        private static BigDecimal[] cuts(List<PoolMember> members, boolean[] retired, boolean[] held,
490	                boolean[] active, BigDecimal pot) {
491	            BigDecimal[] cuts = new BigDecimal[members.size()];
492	            BigDecimal shares = BigDecimal.ZERO;
493	            for (int i = 0; i < members.size(); i++) {
494	                if (active[i] && !retired[i] && !held[i]) {
495	                    shares = shares.add(members.get(i).getShare());
496	                }
497	            }
498	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
499	            int smallest = -1;
500	        int last = -1;
501	            for (int i = 0; i < members.size(); i++) {
502	                if (!active[i]) {
503	                    continue;
504	                }
505	                BigDecimal share = members.get(i).getShare();
506	                boolean cut = !retired[i] && !held[i] && shares.signum() > 0;
507	                cuts[i] = cut ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
508	                        : BigDecimal.ZERO.setScale(2);
509	                sum = sum.add(cuts[i]);
510	                if (cut && share.signum() > 0) {
511	                    last = i;
512	                }
513	                if (cut && cuts[i].signum() != 0
514	                        && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
515	                    smallest = i;
516	                }
517	            }
518	            int to = smallest >= 0 ? smallest : last;
519	            if (to >= 0) {
520	                cuts[to] = cuts[to].add(pot.setScale(2).subtract(sum));
521	            }
522	            return cuts;
523	        }
524	    }
