829	import org.springframework.transaction.annotation.Transactional;
830	
831	/** Keeps each sheet's pools and their members. */
832	@Service
833	public class PoolService {
834	
835	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
836	    private static final int MAX_DEPTH = 3;
837	
838	    private final PoolRepository pools;
839	    private final PersonRepository people;
840	    private final SheetService sheets;
841	    private final Audit audit;
842	
843	    public PoolService(PoolRepository pools, PersonRepository people, SheetService sheets, Audit audit) {
844	        this.pools = pools;
845	        this.people = people;
846	        this.sheets = sheets;
847	        this.audit = audit;
848	    }
849	
850	    /** The sheet's pools, in the order they were added. */
851	    @Transactional(readOnly = true)
852	    public List<Pool> list(String sheetId) {
853	        return pools.findBySheetIdOrderByIdAsc(sheetId);
854	    }
855	
856	    /** Add a pool by a name (surrounding spaces removed); a blank name, or one already taken, is refused. */
857	    @Transactional
858	    public Pool add(String sheetId, String user, String name) {
859	        sheets.today(sheetId);
860	        String n = name == null ? "" : name.trim();
861	        if (n.isEmpty()) {
862	            throw new PoolRefusedException("Enter a pool name.");
863	        }
864	        if (pools.existsBySheetIdAndName(sheetId, n)) {
865	            throw new PoolRefusedException("\"" + n + "\" is already a pool.");
866	        }
867	        Pool saved = pools.saveAndFlush(new Pool(sheetId, n));
868	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + n);
869	        return saved;
870	    }
871	
872	    /** Add a member to a pool with a share percent: a person of the sheet, or another of its pools (poolId).
873	     *  Refused: a share not more than 0.00 and at most 100.00 in two decimals; a person already in it; a pool
874	     *  that would contain itself through any chain, that is already a member of a pool, or that would make a
875	     *  chain of pools more than three deep; a to-date before the from-date (both optional). */
876	    @Transactional
877	    public Pool addMember(String sheetId, String user, long poolId, Long personId, Long memberPoolId,
878	            BigDecimal share, LocalDate from, LocalDate to) {
879	        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
880	                .orElseThrow(() -> new PoolRefusedException("No such pool."));
881	        Person person = personId == null ? null : people.findByIdAndSheetId(personId, sheetId).orElse(null);
882	        Pool member = memberPoolId == null ? null : pools.findByIdAndSheetId(memberPoolId, sheetId).orElse(null);
883	        if ((person == null) == (member == null)) {
884	            throw new PoolRefusedException("Choose a person or a pool.");
885	        }
886	        if (share == null || share.stripTrailingZeros().scale() > 2 || share.signum() <= 0
887	                || share.compareTo(HUNDRED) > 0) {
888	            throw new PoolRefusedException("Enter a share more than 0.00 and at most 100.00, in two decimals.");
889	        }
890	        if (from != null && to != null && to.isBefore(from)) {
891	            throw new PoolRefusedException("A membership cannot end before it starts.");
892	        }
893	        BigDecimal s = share.setScale(2);
894	        String name;
895	        if (person != null) {
896	            if (pool.hasMember(person.getId())) {
897	                throw new PoolRefusedException(person.getName() + " is already in " + pool.getName() + ".");
898	            }
899	            pool.addMember(person.getId(), s, from, to);
900	            name = person.getName();
901	        } else {
902	            refuseMemberPool(sheetId, pool, member);
903	            pool.addMemberPool(member.getId(), s, from, to);
904	            name = member.getName();
905	        }
906	        Pool saved = pools.saveAndFlush(pool);
907	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
908	                + " name=" + name + " share=" + s.toPlainString() + (from == null ? "" : " from=" + from)
909	                + (to == null ? "" : " to=" + to));
910	        return saved;
911	    }
912	
913	    /** Refuse making a pool a member of another when it would contain itself, is already a member of a pool,
914	     *  or the chain of pools would be more than three deep. */
915	    private void refuseMemberPool(String sheetId, Pool pool, Pool member) {
916	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
917	        Map<Long, Long> parentOf = new HashMap<>();
918	        for (Pool p : all) {
919	            for (PoolMember m : p.getMembers()) {
920	                if (m.getMemberPoolId() != null) {
921	                    parentOf.put(m.getMemberPoolId(), p.getId());
922	                }
923	            }
924	        }
925	        int levelsAbove = 0;
926	        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
927	            if (at.equals(member.getId())) {
928	                throw new PoolRefusedException(member.getName() + " cannot contain itself.");
929	            }
930	            levelsAbove++;
931	        }
932	        Long above = parentOf.get(member.getId());
933	        if (above != null) {
934	            String in = all.stream().filter(p -> p.getId().equals(above)).map(Pool::getName).findFirst().orElse("");
935	            throw new PoolRefusedException(member.getName() + " is already in " + in + ".");
936	        }
937	        if (levelsAbove + depth(member, all) > MAX_DEPTH) {
938	            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep.");
939	        }
940	    }
941	
942	    /** How many levels of pools a pool heads: 1, and the deepest of the pools in it. */
943	    private static int depth(Pool pool, List<Pool> all) {
944	        int below = 0;
945	        for (PoolMember m : pool.getMembers()) {
946	            if (m.getMemberPoolId() != null) {
947	                Pool child = all.stream().filter(p -> p.getId().equals(m.getMemberPoolId())).findFirst().orElse(null);
948	                if (child != null) {
949	                    below = Math.max(below, depth(child, all));
950	                }
951	            }
952	        }
953	        return 1 + below;
954	    }
955	}
